SELECT id, 10, 0, 10, DATE_ADD(NOW(), INTERVAL 30 DAY) FROM users WHERE email = 'rtumi.m@icloud.com' 
ON DUPLICATE KEY UPDATE totalCredits = totalCredits + 10, remainingCredits = remainingCredits + 10, updatedAt = NOW();

